import boto3

def redact_unsafe(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        Text=text,
        LanguageCode='en'
    )
    redacted_text = text
    for label in response['Labels']:
        if label['Name'] == 'TOXICITY' and label['Score'] > 0.5:
            redacted_text = redacted_text.replace(label['DetectedText'], '[REDACTED]')
    return redacted_text

if __name__ == '__main__':
    sample_text = 'This is a sample text with some unsafe content.'
    print(redact_unsafe(sample_text))

import os
import json
import requests

API_KEY = os.getenv('PERSPECTIVE_API_KEY')
ANALYZE_ENDPOINT = 'https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze'

def moderate_text(text):
    data = {
        'comment': {'text': text},
        'languages': ['en'],
        'requestedAttributes': {'TOXICITY': {}}
    }
    params = {'key': API_KEY}
    response = requests.post(ANALYZE_ENDPOINT, data=json.dumps(data), params=params, headers={'Content-Type': 'application/json'})
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception('Failed to fetch results from Perspective API')

if __name__ == '__main__':
    user_text = 'Sample text to moderate.'
    result = moderate_text(user_text)
    print(result)
